update public.study_materials
set body_md=replace(
  body_md,
  'Art. 156 — pedido de reconsideração: é dirigido à autoridade que expediu o ato ou proferiu a primeira decisão; não pode ser renovado.',
  'Art. 156 — pedido de reconsideração: é dirigido à autoridade que expediu o ato ou proferiu a primeira decisão; não pode ser renovado. O parágrafo único determina que o requerimento e o pedido de reconsideração sejam despachados em cinco dias e decididos em até trinta dias.'
)||E'\n\n## 91. Lei Orgânica Nacional das Polícias Civis — disposições finais, transição e direitos promulgados — Lei nº 14.735/2023, arts. 30 e 36 a 50\n\n### Complemento do art. 30 — partes vetadas promulgadas em 13/06/2024\n\nO texto atualizado da Lei nº 14.735/2023 não deve ser estudado apenas com a redação originalmente sancionada em 2023. Em 13/06/2024, foram promulgadas partes vetadas do art. 30, que passaram a integrar a lei: (a) licença remunerada para mandato classista, com mínimo de três dirigentes por Estado para confederações, federações e sindicatos; (b) licença remunerada para pelo menos três dirigentes em associação nacional ou de abrangência territorial do ente, conforme representatividade e antiguidade por cargo; (c) carga horária mensal efetiva limitada pela lei local, nunca superior a 40 horas semanais, garantidos direitos remuneratórios, indenizatórios e horas extraordinárias; (d) auxílio-saúde de caráter indenizatório, conforme lei local; e (e) adicional indenizatório para quem assume funções administrativas, assessoramento, coordenação, direção e chefia de investigação, cartório ou plantão, nos termos da lei do ente (§ 8º).\n\nOutras regras importantes do art. 30: o tempo de afastamento para mandato eletivo/classista ou cessão a órgão de natureza pública especificada no § 10 conta como efetivo exercício no serviço policial, mantendo direitos para promoção e progressão; há possibilidade de promoção póstuma (§ 12); não pode haver promoção enquanto perdurarem os efeitos de condenação judicial transitada em julgado ou condenação administrativa definitiva sem recurso/revisão (§ 14); a estabilidade é adquirida após três anos de efetivo exercício (§ 15); e é garantida promoção classe a classe, admitida promoção extraordinária nas hipóteses legais (§ 20). Aposentados conservam direitos específicos dos incisos indicados no § 2º e o porte de arma na forma da legislação (§ 3º).\n\n**Pegadinha:** a carga horária máxima nacional é 40 horas semanais, mas a lei do ente federativo define a duração concreta. A Lei Orgânica Nacional não fixa automaticamente uma escala uniforme para todos os Estados.\n\n### Disposições finais e transitórias — arts. 36 a 50\n\n- **Art. 36:** o poder público deve assegurar instalações policiais seguras e funcionais, além de número adequado de servidores para atendimento eficiente.\n- **Art. 37:** o ente federativo pode criar Fundo Especial da Polícia Civil, destinado preferencialmente à valorização remuneratória e a investimentos em equipamentos, infraestrutura, tecnologia, capacitação e modernização. A criação é facultativa (“pode”), não obrigatória.\n- **Art. 38:** na criação do cargo de Oficial Investigador, os cargos efetivos existentes podem ser transformados, renomeados ou aproveitados pela lei local, respeitadas similitude e equivalência de atribuições. No Acre, a LC nº 496/2025 promoveu a unificação de Agente e Escrivão sob a nomenclatura Oficial Investigador.\n- **Art. 39:** a estrutura e as atribuições dos cargos de perícia oficial nas unidades técnico-científicas devem ser definidas em lei específica, observadas as normas gerais federais e as leis estaduais.\n- **Art. 40:** é vedada a custódia de preso ou adolescente infrator nas dependências das Polícias Civis, mesmo provisoriamente, salvo interesse fundamentado na investigação policial.\n- **Art. 41:** funções gratificadas de assessoramento e chefia da Polícia Civil são privativas de policiais civis.\n- **Arts. 42 e 43:** vetados.\n- **Art. 44:** institui o Conselho Nacional da Polícia Civil, com competência consultiva e deliberativa sobre políticas públicas institucionais de padronização e intercâmbio nas áreas de competência das Polícias Civis; composição e regimento são definidos em decreto.\n- **Art. 45:** admite plataformas tecnológicas para registros cartorários, respeitadas as circunstâncias de atuação presencial das equipes.\n- **Art. 46:** a lei estadual deve dispor sobre a aplicação de data-base para recomposição salarial dos servidores policiais civis.\n- **Art. 47:** o Dia Nacional da Polícia Civil é 5 de abril.\n- **Art. 48:** vetado.\n- **Art. 49:** leis locais permanecem válidas naquilo que não for incompatível com a Lei Orgânica Nacional.\n- **Art. 50:** a lei entrou em vigor na data da publicação.\n\n**Como a IDECAN pode cobrar:** diferença entre “pode criar” (Fundo Especial, art. 37) e “deve assegurar” (instalações e efetivo, art. 36); exceção à vedação de custódia (interesse fundamentado na investigação, art. 40); privatividade das funções de chefia gratificada (art. 41); natureza consultiva e deliberativa do Conselho Nacional (art. 44); data de 5 de abril (art. 47); e prevalência das normas locais compatíveis (art. 49).\n\n**Fontes oficiais:** Lei nº 14.735/2023, texto atualizado no Planalto: https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14735.htm ; promulgação das partes vetadas em 13/06/2024, constante do próprio texto atualizado; LC nº 496/2025 do Acre: https://legis.ac.gov.br/detalhar/6527.\n',
source_note='Lei nº 14.735/2023, arts. 30 e 36–50, texto atualizado no Planalto incluindo promulgação de partes vetadas em 13/06/2024; LC nº 496/2025 do Acre.',
updated_at=now()
where slug='pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025';

with q as (select * from (values
('pcac-lc39-petition-decision-58','LC nº 39/1993 — prazos de decisão','O parágrafo único do art. 156 da LC nº 39/1993 determina que o requerimento e o pedido de reconsideração sejam:','(A) despachados em 10 dias e decididos em 60 dias.\n(B) despachados em 5 dias e decididos em 30 dias.\n(C) despachados e decididos em 15 dias.\n(D) decididos em 5 dias, sem prazo para despacho.\n(E) despachados em 30 dias e decididos em 90 dias.','B','O parágrafo único do art. 156 prevê despacho em cinco dias e decisão dentro de trinta dias.'),
('pcac-national-transition-59','Lei nº 14.735/2023 — criação do Oficial Investigador','Segundo o art. 38 da Lei nº 14.735/2023, na criação do cargo de Oficial Investigador, os cargos efetivos existentes na Polícia Civil:','(A) devem ser extintos sem aproveitamento.\n(B) podem ser transformados, renomeados ou aproveitados pela lei local, respeitadas similitude e equivalência de atribuições.\n(C) são automaticamente convertidos em Delegado.\n(D) só podem ser aproveitados por concurso externo.\n(E) não podem sofrer alteração de nomenclatura.','B','O art. 38 prevê transformação, renomeação ou aproveitamento pela lei do ente, respeitando similitude e equivalência das atribuições.'),
('pcac-national-custody-60','Lei nº 14.735/2023 — custódia de presos','O art. 40 da Lei nº 14.735/2023 veda a custódia de preso ou adolescente infrator nas unidades da Polícia Civil, exceto:','(A) quando faltar vaga no sistema penitenciário, automaticamente.\n(B) por decisão do chefe de plantão, sem motivação.\n(C) quando houver interesse fundamentado na investigação policial.\n(D) por prazo indeterminado a pedido do Ministério Público.\n(E) sempre que houver flagrante.','C','O art. 40 admite exceção apenas quando houver interesse fundamentado na investigação policial.'),
('pcac-national-chief-61','Lei nº 14.735/2023 — funções gratificadas','Conforme o art. 41 da Lei nº 14.735/2023, as funções gratificadas de assessoramento e chefia da Polícia Civil são privativas:','(A) de qualquer servidor público estadual.\n(B) de policiais civis.\n(C) de servidores do Poder Judiciário.\n(D) de agentes políticos.\n(E) de profissionais terceirizados.','B','O art. 41 estabelece que as funções gratificadas de assessoramento e chefia da Polícia Civil são privativas de policiais civis.'),
('pcac-national-council-62','Lei nº 14.735/2023 — Conselho Nacional da Polícia Civil','O Conselho Nacional da Polícia Civil, instituído pelo art. 44 da Lei nº 14.735/2023, possui competência:','(A) exclusivamente jurisdicional.\n(B) consultiva e deliberativa sobre políticas institucionais de padronização e intercâmbio.\n(C) exclusivamente disciplinar sobre todos os servidores estaduais.\n(D) legislativa para editar leis estaduais.\n(E) de substituir os Conselhos Superiores estaduais.','B','O art. 44 atribui ao Conselho Nacional competência consultiva e deliberativa nas políticas institucionais de padronização e intercâmbio.'),
('pcac-national-cartorial-63','Lei nº 14.735/2023 — registros cartorários','O art. 45 da Lei nº 14.735/2023 permite a adoção de plataformas tecnológicas para registros cartorários, desde que:','(A) substituam integralmente toda atuação presencial.\n(B) sejam utilizadas somente por Delegados.\n(C) sejam respeitadas as circunstâncias de atuação presencial das equipes envolvidas.\n(D) sejam mantidas exclusivamente em papel.\n(E) dependam de autorização judicial em cada registro.','C','O art. 45 autoriza plataformas tecnológicas, mas ressalva as circunstâncias de atuação presencial das equipes.'),
('pcac-national-day-64','Lei nº 14.735/2023 — Dia Nacional da Polícia Civil','De acordo com o art. 47 da Lei nº 14.735/2023, o Dia Nacional da Polícia Civil é comemorado em:','(A) 21 de abril.\n(B) 5 de abril.\n(C) 23 de novembro.\n(D) 28 de outubro.\n(E) 10 de maio.','B','O art. 47 fixa o dia 5 de abril como Dia Nacional da Polícia Civil.'),
('pcac-national-local-laws-65','Lei nº 14.735/2023 — compatibilidade de leis locais','Segundo o art. 49 da Lei nº 14.735/2023:','(A) todas as leis estaduais de Polícia Civil foram revogadas.\n(B) as leis locais permanecem válidas naquilo que não seja incompatível com a Lei Orgânica Nacional.\n(C) a lei nacional só se aplica se houver autorização do Governador.\n(D) as leis estaduais prevalecem mesmo quando incompatíveis.\n(E) a Lei Orgânica Nacional não tem aplicação imediata.','B','O art. 49 preserva as leis locais compatíveis com a Lei Orgânica Nacional.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
